def set_zeroes(matrix: list[list[int]]) -> list[list[int]]:
    m, n = len(matrix), len(matrix[0])
    rows, cols = set(), set()
    for r in range(m):
        for c in range(n):
            if matrix[r][c] == 0:
                rows.add(r)
                cols.add(c)
    res = [list(row) for row in matrix]
    for r in range(m):
        for c in range(n):
            if r in rows or c in cols:
                res[r][c] = 0
    return res
